document.addEventListener('DOMContentLoaded', () => { if (typeof Magnifier !== 'undefined') { Magnifier.bind('.K', {zoom: 5, size: 500}); } const copyBtn = document.getElementById('js-deck-copy-btn'); const tooltip = document.getElementById('js-hscard-tooltip'); const tooltipImg = tooltip.querySelector('img'); const OFFSET = -30; const Localization = { locale: (document.documentElement.lang || 'enUS').replace('-', ''), dict: { enUS: { 'changelog.header': 'Changelog', 'deck.code': 'Deck code', 'deck.copy': 'Copy Deck', 'deck.copied': 'Copied!', 'deck.hint': 'Copy the code to import in-game', 'meta.patch': 'Patch {{version}}', 'meta.winrate': 'Winrate {{rate}}', 'meta.format': 'Standard', 'meta.rank.legend': 'Legend', 'replays.header': 'Replays ({{count}})', 'replays.meta.coin': 'with coin', 'replays.win': 'Win', 'replays.loss': 'Loss', 'replays.easy': 'Easy', 'replays.medium': 'Medium', 'replays.hard': 'Hard', 'showcase.hint': 'Click or tap to enlarge', 'tips.warning': 'Warning', 'tips.info': 'Tip', 'tips.question': 'Question', }, ruRU: { 'changelog.header': 'История обновлений', 'deck.code': 'Код колоды', 'deck.copy': 'Взять колоду', 'deck.copied': 'Скопировано!', 'deck.hint': 'Скопируйте код и создайте новую колоду в игре', 'meta.patch': 'Патч {{version}}', 'meta.winrate': 'Винрейт {{rate}}', 'meta.format': 'Стандарт', 'meta.rank.legend': 'Легенда', 'replays.header': 'Записи игр ({{count}})', 'replays.meta.coin': 'с монетки', 'replays.win': 'Победа', 'replays.loss': 'Поражение', 'replays.easy': 'Низкая сложность', 'replays.medium': 'Средняя сложность', 'replays.hard': 'Высокая сложность', 'showcase.hint': 'Нажмите или коснитесь картинки для увеличения', 'tips.warning': 'Внимание', 'tips.info': 'Совет', 'tips.question': 'Вопрос', }, }, getText(key, vars = {}) { return Object.entries(vars).reduce((text, [token, value]) => { return text.replace(new RegExp(`\\{\\{${token}\\}\\}`, 'g'), value); }, (this.dict[this.locale] || this.dict.enUS)[key] || key); }, getVariables(el) { return Array.from(el.attributes).reduce((vars, attr) => { if (attr.name.startsWith('data-i18n-var-')) { vars[attr.name.replace('data-i18n-var-', '')] = attr.value; } return vars; }, {}); }, init() { document.querySelectorAll('[data-i18n]').forEach(el => { const key = el.getAttribute('data-i18n'); el.textContent = this.getText(key, this.getVariables(el)); }); document.querySelectorAll('[data-i18n-title]').forEach(el => { const key = el.getAttribute('data-i18n-title'); el.title = this.getText(key, this.getVariables(el)); }); }, }; function positionTooltip(link, imgWidth, imgHeight) { const rect = link.getBoundingClientRect(); const centerX = rect.left + (rect.width / 2) - (imgWidth / 2); const leftX = rect.left; const rightX = rect.right - imgWidth; const bottomY = rect.bottom + OFFSET; const topY = rect.top - imgHeight - OFFSET; let finalX, finalY; if (centerX >= 0 && centerX + imgWidth <= window.innerWidth) { finalX = centerX; } else if (leftX + imgWidth <= window.innerWidth) { finalX = leftX; } else { finalX = rightX; } if (bottomY + imgHeight <= window.innerHeight || topY < 0) { finalY = bottomY; } else { finalY = topY; } tooltip.style.left = `${finalX + window.scrollX}px`; tooltip.style.top = `${finalY + window.scrollY}px`; tooltip.style.display = 'block'; } function loadCardImage(id, dbfId) { return new Promise((resolve, reject) => { if (!id) { reject(new Error('Не передан строковый ID карты')); return; } const localUrl = `../../cards/${Localization.locale}/${id}-${dbfId}.webp`; const remoteUrl = `https://art.hearthstonejson.com/v1/render/latest/${Localization.locale}/256x/${id}.png`; const preloadImg = new Image(); preloadImg.onload = () => resolve(preloadImg); preloadImg.onerror = () => { if (!preloadImg.src.includes('cards/')) { reject(new Error(`Не удалось загрузить арт карты ни локально, ни с CDN: ${id}`)); return; } preloadImg.src = remoteUrl; }; preloadImg.src = localUrl; }); } copyBtn && copyBtn.addEventListener('click', () => { const deckcode = document.getElementById('js-deck-copy-input'); const toast = document.getElementById('js-deck-copy-toast'); if (deckcode && toast) { deckcode.focus(); deckcode.select(); try { if (document.execCommand('copy')) { toast.classList.add('bR'); setTimeout(() => toast.classList.remove('bR'), 2000); } } catch (err) {} } }); document.body.addEventListener('mouseover', (e) => { if (e.target.classList.contains('a')) { const link = e.target; const id = link.getAttribute('data-id') || ''; const dbfId = link.getAttribute('data-dbf') || '0'; if (tooltipImg.getAttribute('data-dbf') === dbfId && tooltipImg.complete && tooltipImg.naturalWidth > 0) { positionTooltip(link, tooltipImg.naturalWidth, tooltipImg.naturalHeight); return; } loadCardImage(id, dbfId).then((loadedImg) => { if (!link.matches(':hover')) return; tooltipImg.src = loadedImg.src; tooltipImg.setAttribute('data-dbf', dbfId); positionTooltip(link, loadedImg.width, loadedImg.height); }).catch((e) => { console.warn(e.message); }); } }); document.body.addEventListener('mouseout', (e) => { if (e.target.classList.contains('a')) { tooltip.style.display = 'none'; } }); document.querySelectorAll('img.H').forEach(async (img) => { const id = img.getAttribute('data-id'); const dbfId = img.getAttribute('data-dbf') || '0'; try { const loadedImg = await loadCardImage(id, dbfId); const rowItem = img.closest('.G'); rowItem.classList.add('aX'); img.src = loadedImg.src; img.classList.remove('q'); setTimeout(() => rowItem.classList.remove('aX'), 250); } catch (e) { console.warn(e.message); } }); Localization.init(); });